CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(100) NOT NULL, email varchar(255) NOT NULL UNIQUE, password_hash text NOT NULL, role varchar(30) NOT NULL DEFAULT 'owner', avatar_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name varchar(100) NOT NULL, description varchar(500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,name));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, category_id uuid REFERENCES categories(id) ON DELETE SET NULL, name varchar(150) NOT NULL, sku varchar(80) NOT NULL, description text, price numeric(12,2) NOT NULL DEFAULT 0 CHECK(price>=0), stock_quantity integer NOT NULL DEFAULT 0 CHECK(stock_quantity>=0), low_stock_threshold integer NOT NULL DEFAULT 5 CHECK(low_stock_threshold>=0), image_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,sku));
CREATE TABLE stock_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type varchar(20) NOT NULL CHECK(type IN ('in','out','adjustment')), quantity integer NOT NULL CHECK(quantity<>0), note varchar(500), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_categories_user_name ON categories(user_id,name); CREATE INDEX idx_products_user_search ON products(user_id,name,sku); CREATE INDEX idx_products_user_category ON products(user_id,category_id); CREATE INDEX idx_movements_user_created ON stock_movements(user_id,created_at DESC); CREATE INDEX idx_movements_product_created ON stock_movements(product_id,created_at DESC);
